// Which photos the PDF needs: the logo + one catalogue photo per item (photos.json maps item codes to JPEGs).
const o = $('Confirm In').first().json.order || {};
let idx = {};
try { idx = $('Photo Index').first().json || {}; } catch (e) { idx = {}; }
const photos = idx.photos || {};
const norm = (s) => String(s || '').toUpperCase().replace(/[^A-Z0-9]/g, '');
const keys = (code) => { const n = norm(code), c = n.replace(/^(RC|RJ|RAJ|RT|TESLA|T)(?=\d)/, ''), z = (s) => s.replace(/(^|[A-Z])0+(?=\d)/g, '$1'); return [n, c, z(n), z(c)].filter(Boolean); };
let items = [];
try { items = typeof o.items === 'string' ? JSON.parse(o.items || '[]') : (o.items || []); } catch (e) { items = []; }
const urls = new Map(); // url -> line numbers (-1 = logo)
const add = (u, i) => { if (!u) return; const full = 'https://rajcreation.info/' + u; if (!urls.has(full)) urls.set(full, []); urls.get(full).push(i); };
add(idx.logo || 'assets/logo-pdf.jpg', -1);
items.forEach((x, i) => { const k = keys(x.code).find((k) => photos[k]); if (k) add(photos[k], i); });
return [...urls].slice(0, 80).map(([url, idxs]) => ({ json: { url, idxs } }));

// Order confirmation PDF for Raj Creation, written by hand (no libraries): A4, Helvetica, JPEG photos.
// makeOrderPdf(order, { logo: Buffer|null, photos: { [line index]: Buffer } }) -> Buffer
function makeOrderPdf(o, img) {
  const W = 595.28, H = 841.89, M = 36;
  const ACC = '0.612 0.239 0.353', INK = '0.141 0.11 0.133', MUTED = '0.43 0.38 0.41', LINE = '0.88 0.84 0.81', SOFT = '0.976 0.945 0.953', WHITE = '1 1 1';
  // Helvetica / Helvetica-Bold widths (1/1000 em) for characters 32-126
  const HV = [278,278,355,556,556,889,667,191,333,333,389,584,278,333,278,278,556,556,556,556,556,556,556,556,556,556,278,278,584,584,584,556,1015,667,667,722,722,667,611,778,722,278,500,667,556,833,722,778,667,778,722,667,611,722,667,944,667,667,611,278,278,278,469,556,333,556,556,500,556,556,278,556,556,222,222,500,222,833,556,556,556,556,333,500,278,556,500,722,500,500,500,334,260,334,584];
  const HB = [278,333,474,556,556,889,722,238,333,333,389,584,278,333,278,278,556,556,556,556,556,556,556,556,556,556,333,333,584,584,584,611,975,722,722,722,722,667,611,778,722,278,556,722,611,833,722,778,667,778,722,667,611,722,667,944,667,667,611,333,278,333,584,556,333,556,611,556,611,556,333,611,611,278,278,556,278,889,611,611,611,611,389,556,333,611,556,778,556,556,500,389,280,389,584];
  // Text as WinAnsi (Latin-1): ₹ -> Rs., dashes, quotes; scripts the standard fonts cannot show are dropped.
  const latin = (s) => String(s === undefined || s === null ? '' : s)
    .replace(/₹\s?/g, 'Rs. ').replace(/[–—]/g, '-').replace(/[‘’]/g, "'").replace(/[“”]/g, '"').replace(/…/g, '...')
    .replace(/[^\x20-\x7e\xa0-\xff]/g, '').replace(/\s+/g, ' ').trim();
  const tw = (s, size, bold) => { let w = 0; for (const ch of latin(s)) { const c = ch.charCodeAt(0); w += (c >= 32 && c <= 126 ? (bold ? HB : HV)[c - 32] : c === 0xd7 ? 584 : 556); } return w * size / 1000; };
  const fit = (s, size, bold, max) => { s = latin(s); if (tw(s, size, bold) <= max) return s; while (s.length > 1 && tw(s + '...', size, bold) > max) s = s.slice(0, -1); return s.trimEnd() + '...'; };
  const esc = (s) => latin(s).replace(/\\/g, '\\\\').replace(/\(/g, '\\(').replace(/\)/g, '\\)');
  const n2 = (v) => { const n = Number(v) || 0; return Math.round(n * 100) / 100; };
  const money = (v) => { // Indian grouping: 11,710.13
    const n = n2(v), neg = n < 0, a = Math.abs(n), int = Math.floor(a), dec = Math.round((a - int) * 100);
    let s = String(int); if (s.length > 3) { const last = s.slice(-3); let rest = s.slice(0, -3); const parts = []; while (rest.length > 2) { parts.unshift(rest.slice(-2)); rest = rest.slice(0, -2); } if (rest) parts.unshift(rest); s = parts.join(',') + ',' + last; }
    return (neg ? '-' : '') + 'Rs. ' + s + (dec ? '.' + String(dec).padStart(2, '0') : '');
  };
  const MON = ['Jan', 'Feb', 'Mar', 'Apr', 'May', 'Jun', 'Jul', 'Aug', 'Sep', 'Oct', 'Nov', 'Dec'];
  const day = (s) => { const m = String(s || '').match(/^(\d{4})-(\d{2})-(\d{2})/); return m ? m[3] + ' ' + MON[+m[2] - 1] + ' ' + m[1] : String(s || ''); };

  // ---- images ----
  function jpegInfo(b) {
    if (!b || b.length < 4 || b[0] !== 0xff || b[1] !== 0xd8) return null;
    let i = 2;
    while (i + 9 < b.length) {
      if (b[i] !== 0xff) { i++; continue; }
      const mk = b[i + 1];
      if (mk === 0xd8 || mk === 0x01 || mk === 0xff || (mk >= 0xd0 && mk <= 0xd7)) { i += mk === 0xff ? 1 : 2; continue; }
      const len = b.readUInt16BE(i + 2);
      if (mk >= 0xc0 && mk <= 0xcf && mk !== 0xc4 && mk !== 0xc8 && mk !== 0xcc) return { h: b.readUInt16BE(i + 5), w: b.readUInt16BE(i + 7), comps: b[i + 9] };
      i += 2 + len;
    }
    return null;
  }
  const images = []; // { buf, info, name }
  const imageFor = (buf) => {
    if (!buf) return null;
    let im = images.find((x) => x.buf === buf || (x.buf.length === buf.length && x.buf.equals(buf)));
    if (im) return im;
    const info = jpegInfo(buf);
    if (!info || !info.w || !info.h || ![1, 3, 4].includes(info.comps)) return null;
    im = { buf, info, name: 'Im' + (images.length + 1) };
    images.push(im);
    return im;
  };
  const logo = imageFor(img && img.logo);

  // ---- page drawing ----
  const pages = [];
  let c = null; // current page content (array of strings)
  const T = (x, y, s, size, bold, color) => c.push('BT /' + (bold ? 'F2' : 'F1') + ' ' + size + ' Tf ' + (color || INK) + ' rg ' + x.toFixed(2) + ' ' + y.toFixed(2) + ' Td (' + esc(s) + ') Tj ET');
  const TR = (xr, y, s, size, bold, color) => T(xr - tw(s, size, bold), y, s, size, bold, color);
  const TC = (xc, y, s, size, bold, color) => T(xc - tw(s, size, bold) / 2, y, s, size, bold, color);
  const R = (x, y, w, h, fill) => c.push(fill + ' rg ' + x.toFixed(2) + ' ' + y.toFixed(2) + ' ' + w.toFixed(2) + ' ' + h.toFixed(2) + ' re f');
  const L = (x1, y1, x2, y2, color, wd) => c.push(color + ' RG ' + (wd || 0.6) + ' w ' + x1.toFixed(2) + ' ' + y1.toFixed(2) + ' m ' + x2.toFixed(2) + ' ' + y2.toFixed(2) + ' l S');
  const IMG = (im, x, y, w, h) => c.push('q ' + w.toFixed(2) + ' 0 0 ' + h.toFixed(2) + ' ' + x.toFixed(2) + ' ' + y.toFixed(2) + ' cm /' + im.name + ' Do Q');
  const fitImg = (im, x, y, bw, bh) => { const s = Math.min(bw / im.info.w, bh / im.info.h); const w = im.info.w * s, h = im.info.h * s; IMG(im, x + (bw - w) / 2, y + (bh - h) / 2, w, h); };
  const newPage = () => { c = []; pages.push(c); R(0, H - 6, W, 6, ACC); };

  const items = Array.isArray(o.items) ? o.items : (() => { try { return JSON.parse(o.items || '[]'); } catch (e) { return []; } })();
  const revised = Number(o.confirm_count) > 1;
  const title = revised ? 'REVISED ORDER CONFIRMATION' : 'ORDER CONFIRMATION';

  // first page header
  newPage();
  let y = H - M - 4;
  if (logo) fitImg(logo, M, y - 52, 120, 52);
  else T(M, y - 30, 'Raj Creation', 20, true, ACC);
  TR(W - M, y - 16, title, revised ? 14 : 17, true, ACC);
  TR(W - M, y - 34, 'Order ' + o.order_id, 11, true);
  TR(W - M, y - 48, 'Date: ' + day(o.confirmed_at || o.updated_at || o.created_at), 9, false, MUTED);
  y -= 66;
  L(M, y, W - M, y, LINE, 0.8);

  // customer + order boxes
  const boxH = 74, boxW = (W - 2 * M - 12) / 2;
  y -= 10 + boxH;
  R(M, y, boxW, boxH, SOFT);
  R(M + boxW + 12, y, boxW, boxH, SOFT);
  T(M + 10, y + boxH - 15, 'BILL TO', 7.5, true, ACC);
  const custLines = [latin(o.shop) || latin(o.name) || 'Customer', latin(o.shop) && latin(o.name) ? latin(o.name) : '', latin(o.city), o.phone ? '+' + String(o.phone).replace(/^91(\d{5})(\d{5})$/, '91 $1 $2') : ''].filter(Boolean).slice(0, 4);
  custLines.forEach((s, i) => T(M + 10, y + boxH - 29 - i * 12, fit(s, i ? 9 : 10.5, !i, boxW - 20), i ? 9 : 10.5, !i));
  const bx = M + boxW + 22;
  T(bx, y + boxH - 15, 'ORDER DETAILS', 7.5, true, ACC);
  const det = [['Business type', o.btype || '-'], ['Price level', o.level || o.btype || '-'], ['Packets / boxes', String(o.packets || items.reduce((s, x) => s + (x.packets || 0), 0))], ['Dozens', String(o.dozens || items.reduce((s, x) => s + (x.packets || 0) * (x.dz || 0), 0))]];
  det.forEach(([k, v], i) => { T(bx, y + boxH - 29 - i * 12, k, 9, false, MUTED); TR(M + 2 * boxW + 2, y + boxH - 29 - i * 12, fit(v, 9, true, boxW - 100), 9, true); });
  y -= 18;

  // table
  const COL = { n: M + 4, photo: M + 24, item: M + 80, qty: M + 286, rateR: W - M - 86, amtR: W - M - 8 };
  const ROW = 54, FOOT = 46;
  const tableHead = () => {
    R(M, y - 20, W - 2 * M, 20, ACC);
    T(COL.n, y - 14, '#', 8.5, true, WHITE);
    T(COL.photo, y - 14, 'Photo', 8.5, true, WHITE);
    T(COL.item, y - 14, 'Item', 8.5, true, WHITE);
    T(COL.qty, y - 14, 'Quantity', 8.5, true, WHITE);
    TR(COL.rateR, y - 14, 'Rate / dozen', 8.5, true, WHITE);
    TR(COL.amtR, y - 14, 'Amount', 8.5, true, WHITE);
    y -= 20;
  };
  tableHead();
  items.forEach((x, i) => {
    if (y - ROW < M + FOOT) {
      newPage();
      y = H - M - 10;
      T(M, y - 10, 'Order ' + o.order_id + ' (continued)', 10, true, ACC);
      y -= 24;
      tableHead();
    }
    const top = y, mid = top - ROW / 2;
    if (i % 2) R(M, top - ROW, W - 2 * M, ROW, SOFT);
    T(COL.n, mid - 3, String(i + 1), 9, false, MUTED);
    const im = imageFor(img && img.photos && img.photos[i]);
    if (im) fitImg(im, COL.photo, top - ROW + 4, 46, ROW - 8);
    else { R(COL.photo, top - ROW + 4, 46, ROW - 8, '0.95 0.93 0.92'); TC(COL.photo + 23, mid - 3, 'no photo', 6.5, false, MUTED); }
    T(COL.item, mid + 4, fit(x.code, 11, true, COL.qty - COL.item - 8), 11, true);
    if (x.desc) T(COL.item, mid - 9, fit(x.desc, 8.5, false, COL.qty - COL.item - 8), 8.5, false, MUTED);
    const unit = x.unit === 'box' ? (x.packets === 1 ? 'box' : 'boxes') : (x.packets === 1 ? 'packet' : 'packets');
    T(COL.qty, mid + 4, x.packets + ' ' + unit + ' x ' + x.dz + ' dz', 9.5, false);
    T(COL.qty, mid - 9, '= ' + (x.packets * x.dz) + ' dozen', 8.5, false, MUTED);
    TR(COL.rateR, mid - 3, money(x.rate), 9.5, false);
    TR(COL.amtR, mid - 3, money(x.amount), 10, true);
    L(M, top - ROW, W - M, top - ROW, LINE, 0.5);
    y -= ROW;
  });

  // totals
  const ship = Number(o.shipping);
  const rows = [['Items total', money(o.items_total)]];
  if (Number(o.handling) > 0) rows.push(['Handling & packing', money(o.handling)]);
  rows.push(['GST ' + (o.gst_pct || 5) + '%', money(o.gst)]);
  rows.push(['Shipping', ship > 0 ? money(ship) : ship === 0 ? 'Free' : 'To be confirmed']);
  const need = rows.length * 16 + 40 + 70;
  if (y - need < M + FOOT) { newPage(); y = H - M - 20; }
  y -= 14;
  const tx = W - M - 230;
  rows.forEach(([k, v]) => { T(tx, y - 10, k, 9.5, false, MUTED); TR(COL.amtR, y - 10, v, 9.5, false); y -= 16; });
  L(tx, y - 2, W - M, y - 2, LINE, 0.8);
  y -= 8;
  R(tx - 8, y - 28, W - M - tx + 8, 28, ACC);
  T(tx, y - 18, 'GRAND TOTAL', 11, true, WHITE);
  TR(COL.amtR, y - 18, money(o.grand_total || (n2(o.total) + Math.max(0, ship || 0))), 13, true, WHITE);
  // notes on the left of the totals
  const notes = ['Rates are per dozen. Items are sold in full packets / boxes.', 'Our team will share the payment and dispatch details.', 'This is only a reference receipt, not the official receipt.', 'The official receipt will be given to you separately.'];
  let ny = y + rows.length * 16 + 4;
  T(M, ny, 'Thank you for your order!', 11, true, ACC);
  notes.forEach((s, i) => T(M, ny - 15 - i * 11, s, 8, false, MUTED));

  // footer on every page
  pages.forEach((p, i) => {
    c = p;
    L(M, M + 22, W - M, M + 22, LINE, 0.6);
    T(M, M + 8, 'Raj Creation  |  Manufacturer of hair accessories  |  rajcreation.info  |  +91 91122 96139', 8, false, MUTED);
    TR(W - M, M + 8, 'Page ' + (i + 1) + ' of ' + pages.length, 8, false, MUTED);
  });

  // ---- write the PDF file ----
  const chunks = [];
  let size = 0;
  const offsets = [];
  const put = (x) => { const b = Buffer.isBuffer(x) ? x : Buffer.from(x, 'latin1'); chunks.push(b); size += b.length; };
  const obj = (n, body) => { offsets[n] = size; put(n + ' 0 obj\n'); if (Array.isArray(body)) body.forEach(put); else put(body); put('\nendobj\n'); };
  // objects: 1 catalog, 2 pages, 3 F1, 4 F2, then images, then page + content pairs
  const firstImg = 5, firstPage = firstImg + images.length;
  put('%PDF-1.4\n%\xe2\xe3\xcf\xd3\n');
  obj(1, '<< /Type /Catalog /Pages 2 0 R >>');
  obj(2, '<< /Type /Pages /Kids [' + pages.map((p, i) => (firstPage + 2 * i) + ' 0 R').join(' ') + '] /Count ' + pages.length + ' >>');
  obj(3, '<< /Type /Font /Subtype /Type1 /BaseFont /Helvetica /Encoding /WinAnsiEncoding >>');
  obj(4, '<< /Type /Font /Subtype /Type1 /BaseFont /Helvetica-Bold /Encoding /WinAnsiEncoding >>');
  images.forEach((im, i) => {
    const cs = im.info.comps === 1 ? '/DeviceGray' : im.info.comps === 4 ? '/DeviceCMYK /Decode [1 0 1 0 1 0 1 0]' : '/DeviceRGB';
    obj(firstImg + i, ['<< /Type /XObject /Subtype /Image /Width ' + im.info.w + ' /Height ' + im.info.h + ' /ColorSpace ' + cs + ' /BitsPerComponent 8 /Filter /DCTDecode /Length ' + im.buf.length + ' >>\nstream\n', im.buf, '\nendstream']);
  });
  const xobj = images.length ? ' /XObject << ' + images.map((im, i) => '/' + im.name + ' ' + (firstImg + i) + ' 0 R').join(' ') + ' >>' : '';
  pages.forEach((p, i) => {
    const content = Buffer.from(p.join('\n'), 'latin1');
    obj(firstPage + 2 * i, '<< /Type /Page /Parent 2 0 R /MediaBox [0 0 ' + W + ' ' + H + '] /Resources << /Font << /F1 3 0 R /F2 4 0 R >>' + xobj + ' >> /Contents ' + (firstPage + 2 * i + 1) + ' 0 R >>');
    obj(firstPage + 2 * i + 1, ['<< /Length ' + content.length + ' >>\nstream\n', content, '\nendstream']);
  });
  const total = firstPage + 2 * pages.length;
  const xref = size;
  put('xref\n0 ' + total + '\n0000000000 65535 f \n');
  for (let n = 1; n < total; n++) put(String(offsets[n]).padStart(10, '0') + ' 00000 n \n');
  put('trailer\n<< /Size ' + total + ' /Root 1 0 R >>\nstartxref\n' + xref + '\n%%EOF\n');
  return Buffer.concat(chunks);
}

const inp = $('Confirm In').first().json;
const o = Object.assign({}, inp.order || {});
try { o.items = typeof o.items === 'string' ? JSON.parse(o.items || '[]') : (o.items || []); } catch (e) { o.items = []; }
const picks = $('Pick Photos').all();
const img = { logo: null, photos: {} };
const all = $input.all();
for (let i = 0; i < all.length; i++) {
  if (!all[i].binary || !all[i].binary.data) continue;
  let buf = null;
  try { buf = await this.helpers.getBinaryDataBuffer(i, 'data'); } catch (e) { buf = null; }
  if (!buf || !buf.length) continue;
  for (const k of (picks[i] && picks[i].json.idxs) || []) { if (k === -1) img.logo = buf; else img.photos[k] = buf; }
}
const pdf = makeOrderPdf(o, img);
const fileName = 'Raj Creation Order ' + o.order_id + '.pdf';
let bin;
try { bin = await this.helpers.prepareBinaryData(pdf, fileName, 'application/pdf'); }
catch (e) { bin = { data: pdf.toString('base64'), mimeType: 'application/pdf', fileName, fileExtension: 'pdf' }; }
return [{ json: { file_name: fileName, bytes: pdf.length, photos: Object.keys(img.photos).length, logo: !!img.logo }, binary: { data: bin } }];

// Who gets the PDF: the customer (a normal message inside their 24-hour window, else the order-confirmed
// template with a "Get confirmation PDF" button) and, after finalizing, a copy for Mahek.
const MAHEK = '919112296139';
const inp = $('Confirm In').first().json;
const o = inp.order || {};
const cu = inp.customer || {};
const mediaId = $('Upload PDF').first().json.id;
const fileName = $('Build PDF').first().json.file_name;
const tpl = {};
for (const it of $('Template Names').all()) if (it.json && it.json.key) tpl[it.json.key] = it.json;
const tname = tpl.confirm && tpl.confirm.status === 'APPROVED' ? tpl.confirm.name : '';
const lang = ['hi', 'gu', 'ta', 'te'].includes(o.lang || cu.lang) ? (o.lang || cu.lang) : 'en';
const inr2 = (n) => '₹' + Number(n || 0).toLocaleString('en-IN', { minimumFractionDigits: Number(n) % 1 ? 2 : 0, maximumFractionDigits: 2 });
const ship = Number(o.shipping) || 0;
const grand = Number(o.grand_total) || (Number(o.total) || 0) + ship;
const name = String(cu.name || o.name || '').trim() || ({ en: 'there', hi: 'जी', gu: 'જી', ta: 'நண்பரே', te: 'గారు' })[lang];
const INCL = { en: ship ? 'incl. GST and shipping' : 'incl. GST · free shipping', hi: ship ? 'GST और शिपिंग सहित' : 'GST सहित · फ्री शिपिंग', gu: ship ? 'GST અને શિપિંગ સહિત' : 'GST સહિત · ફ્રી શિપિંગ', ta: ship ? 'GST மற்றும் ஷிப்பிங் உட்பட' : 'GST உட்பட · இலவச ஷிப்பிங்', te: ship ? 'GST మరియు షిప్పింగ్‌తో కలిపి' : 'GST తో కలిపి · ఉచిత షిప్పింగ్' };
const CAP = {
  en: '✅ *Order confirmed – {id}*\n\nThank you, {name}! Your order with Raj Creation is confirmed.\n💰 Total: *{total}* ({incl})\n\n📄 Your order confirmation is attached. Our team will share the payment and dispatch details with you. 🙏',
  hi: '✅ *ऑर्डर कन्फ़र्म – {id}*\n\nधन्यवाद, {name}! राज क्रिएशन के साथ आपका ऑर्डर कन्फ़र्म हो गया है।\n💰 कुल: *{total}* ({incl})\n\n📄 ऑर्डर कन्फ़र्मेशन साथ में है। पेमेंट और डिस्पैच की जानकारी हमारी टीम आपको देगी। 🙏',
